diff --git a/tests/repro/cross-drive-ignore.js b/tests/repro/cross-drive-ignore.js
new file mode 100644
index 0000000..a5ed908
--- /dev/null
+++ b/tests/repro/cross-drive-ignore.js
@@ -0,0 +1,76 @@
+/**
+ * Reproduction for "files on a different drive are not ignored on Windows".
+ *
+ * On a non-Windows host, Windows path semantics are simulated by temporarily
+ * swapping the shared `node:path` module's methods for `path.win32` while
+ * ESLint (Linter and @eslint/config-array) handles the path. On Windows it
+ * runs natively.
+ *
+ * Run: node tests/repro/cross-drive-ignore.js
+ */
+"use strict";
+
+const path = require("node:path");
+const { Linter } = require("../../lib/api");
+const { FlatConfigArray } = require("../../lib/config/flat-config-array");
+
+const simulate = process.platform !== "win32";
+const posixMethods = { ...path };
+
+function withWin32Path(fn) {
+    if (!simulate) {
+        return fn();
+    }
+    Object.assign(path, path.win32);
+    try {
+        return fn();
+    } finally {
+        Object.assign(path, posixMethods);
+    }
+}
+
+const cwd = "C:\\Project";
+const config = { rules: { "no-undef": "error" } };
+const linter = new Linter({ configType: "flat", cwd });
+
+// Warm up so lazily-loaded rules are required with the real path module.
+new Linter({ configType: "flat" }).verify("foo()", config, "warmup.js");
+
+console.log(`platform: ${process.platform}${simulate ? " (simulating win32 paths)" : ""}`);
+console.log(`cwd/basePath: ${cwd}`);
+console.log(`path.relative(cwd, "F:\\\\foo.js") = ${JSON.stringify(withWin32Path(() => path.relative(cwd, "F:\\foo.js")))}`);
+console.log(`path.relative(cwd, "C:\\\\Other\\\\foo.js") = ${JSON.stringify(withWin32Path(() => path.relative(cwd, "C:\\Other\\foo.js")))}`);
+console.log();
+
+let bug = false;
+
+for (const filename of ["C:\\Project\\foo.js", "C:\\Other\\foo.js", "F:\\foo.js"]) {
+    const insideBase = filename.startsWith(`${cwd}\\`);
+
+    const messages = withWin32Path(() => linter.verify("foo()", config, filename));
+    const status = withWin32Path(() => {
+        const configArray = new FlatConfigArray([config], { basePath: cwd });
+
+        configArray.normalizeSync();
+        return configArray.getConfigStatus(filename);
+    });
+
+    const expectedStatus = insideBase ? "matched" : "external";
+    const ok = status === expectedStatus;
+
+    if (!ok) {
+        bug = true;
+    }
+
+    console.log(`${filename}`);
+    console.log(`  FlatConfigArray#getConfigStatus: ${status} (expected ${expectedStatus}) ${ok ? "OK" : "<-- BUG"}`);
+    console.log(`  Linter#verify messages: ${messages.map(m => `[${m.ruleId}] ${m.message}`).join(" | ")}`);
+}
+
+console.log();
+if (bug) {
+    console.log("REPRODUCED: file on a different drive is treated as inside the base path and gets linted.");
+    process.exitCode = 1;
+} else {
+    console.log("Not reproduced.");
+}
